#!/usr/bin/env python3
"""
Generate original, mathematically accurate SVG medical diagrams for StewardMD PrepNucleus Learn lessons.
Follows StewardMD design rules:
- Palette: #071318 (text/dark), #3D5A54 (muted), #0B6B5B (primary teal), #EAF3F0 (soft teal fill), #B7791F (gold/amber), #B42318 (coral/red).
- Pure SVG, viewBox="0 0 800 520", accessible with <title id="t"> and <desc id="d">.
- White stage (#FFFFFF).
- Crisp typography, explicit labels, no glows, gradients, or backdrops.
"""

import math
import os

OUT_DIR = "prep/lessons/media"
os.makedirs(OUT_DIR, exist_ok=True)

# 1. pharma-dose-response.svg
def gen_pharma_dose_response():
    def x_for(log_c):
        return 160 + (log_c - (-9)) * (500 / 6.0)
    def y_for(pct):
        return 410 - pct * 2.8

    pts_ag = [f"{x_for(lc):.1f} {y_for(100 / (1 + 10**(-(lc - (-7))))):.1f}" for lc in [-9 + i * 0.1 for i in range(61)]]
    pts_comp = [f"{x_for(lc):.1f} {y_for(100 / (1 + 10**(-(lc - (-5.5))))):.1f}" for lc in [-9 + i * 0.1 for i in range(61)]]
    pts_noncomp = [f"{x_for(lc):.1f} {y_for(50 / (1 + 10**(-(lc - (-7))))):.1f}" for lc in [-9 + i * 0.1 for i in range(61)]]
    pts_part = [f"{x_for(lc):.1f} {y_for(60 / (1 + 10**(-(lc - (-7.5))))):.1f}" for lc in [-9 + i * 0.1 for i in range(61)]]

    svg = f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 520" role="img" aria-labelledby="t d"><title id="t">Log dose-response curves and receptor antagonism</title><desc id="d">Sigmoid log concentration-response curves showing a full agonist at Emax 100 percent, a competitive antagonist causing a parallel rightward shift with preserved Emax, a non-competitive antagonist depressing Emax to 50 percent, and a partial agonist reaching submaximal efficacy.</desc><rect width="800" height="520" fill="#FFFFFF"/><text x="400" y="34" font-size="20" font-weight="700" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Dose-response curves and receptor antagonism</text><text x="400" y="56" font-size="12.5" font-weight="400" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Log drug concentration versus percentage maximal biological effect (Emax)</text><line x1="160" y1="410" x2="670" y2="410" stroke="#071318" stroke-width="2"/><line x1="160" y1="410" x2="160" y2="120" stroke="#071318" stroke-width="2"/><line x1="155" y1="130" x2="670" y2="130" stroke="#E0ECE8" stroke-width="1.5" stroke-dasharray="4 4"/><line x1="155" y1="270" x2="670" y2="270" stroke="#E0ECE8" stroke-width="1.5" stroke-dasharray="4 4"/><path d="M {' L '.join(pts_ag)}" fill="none" stroke="#0B6B5B" stroke-width="3.5"/><path d="M {' L '.join(pts_comp)}" fill="none" stroke="#B7791F" stroke-width="3" stroke-dasharray="6 3"/><path d="M {' L '.join(pts_noncomp)}" fill="none" stroke="#B42318" stroke-width="3"/><path d="M {' L '.join(pts_part)}" fill="none" stroke="#2D6A4F" stroke-width="2.5" stroke-dasharray="3 3"/><circle cx="{x_for(-7):.1f}" cy="{y_for(50):.1f}" r="4" fill="#0B6B5B"/><line x1="{x_for(-7):.1f}" y1="{y_for(50):.1f}" x2="{x_for(-7):.1f}" y2="410" stroke="#0B6B5B" stroke-width="1.5" stroke-dasharray="3 3"/><text x="{x_for(-7):.1f}" y="426" font-size="11" font-weight="700" text-anchor="middle" fill="#0B6B5B" font-family="system-ui,sans-serif">EC50</text><circle cx="{x_for(-5.5):.1f}" cy="{y_for(50):.1f}" r="4" fill="#B7791F"/><line x1="{x_for(-5.5):.1f}" y1="{y_for(50):.1f}" x2="{x_for(-5.5):.1f}" y2="410" stroke="#B7791F" stroke-width="1.5" stroke-dasharray="3 3"/><text x="{x_for(-5.5):.1f}" y="426" font-size="11" font-weight="700" text-anchor="middle" fill="#B7791F" font-family="system-ui,sans-serif">shifted EC50</text><text x="190" y="116" font-size="13" font-weight="700" fill="#0B6B5B" font-family="system-ui,sans-serif">Full agonist (Emax 100%)</text><text x="490" y="190" font-size="12.5" font-weight="700" fill="#B7791F" font-family="system-ui,sans-serif">+ Competitive antagonist</text><text x="490" y="206" font-size="11" fill="#3D5A54" font-family="system-ui,sans-serif">(parallel right shift, same Emax)</text><text x="340" y="285" font-size="12.5" font-weight="700" fill="#B42318" font-family="system-ui,sans-serif">+ Non-competitive antagonist</text><text x="340" y="301" font-size="11" fill="#3D5A54" font-family="system-ui,sans-serif">(depressed Emax, insurmountable)</text><text x="210" y="230" font-size="12" font-weight="600" fill="#2D6A4F" font-family="system-ui,sans-serif">Partial agonist</text><text x="400" y="450" font-size="13" font-weight="600" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Log Drug Concentration [M]</text><text x="100" y="265" font-size="13" font-weight="600" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif" transform="rotate(-90 100 265)">Response (% of maximum)</text><text x="145" y="414" font-size="11" text-anchor="end" fill="#3D5A54" font-family="system-ui,sans-serif">0%</text><text x="145" y="274" font-size="11" text-anchor="end" fill="#3D5A54" font-family="system-ui,sans-serif">50%</text><text x="145" y="134" font-size="11" text-anchor="end" fill="#3D5A54" font-family="system-ui,sans-serif">100%</text><text x="{x_for(-9):.1f}" y="440" font-size="11" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">10⁻⁹</text><text x="{x_for(-7):.1f}" y="440" font-size="11" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">10⁻⁷</text><text x="{x_for(-5):.1f}" y="440" font-size="11" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">10⁻⁵</text><text x="{x_for(-3):.1f}" y="440" font-size="11" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">10⁻³</text><text x="400" y="505" font-size="11" font-weight="400" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Competitive antagonists increase EC50 without changing Emax; non-competitive antagonists reduce Emax.</text></svg>'''
    with open(os.path.join(OUT_DIR, "pharma-dose-response.svg"), "w") as f:
        f.write(svg)

# 2. pharma-therapeutic-index.svg
def gen_pharma_therapeutic_index():
    def x_for(d):
        return 160 + d * 50
    def y_for(pct):
        return 410 - pct * 2.8

    # ED curve: ED50 at dose index 3 (x=310)
    pts_ed = [f"{x_for(d):.1f} {y_for(100 / (1 + math.exp(-1.5 * (d - 3)))):.1f}" for d in [i * 0.15 for i in range(65)]]
    # TD curve: TD50 at dose index 7 (x=510)
    pts_td = [f"{x_for(d):.1f} {y_for(100 / (1 + math.exp(-1.5 * (d - 7)))):.1f}" for d in [i * 0.15 for i in range(65)]]

    svg = f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 520" role="img" aria-labelledby="t d"><title id="t">Therapeutic index and window</title><desc id="d">Sigmoid population frequency curves for therapeutic efficacy (ED50) and toxicity (TD50). The therapeutic index is TD50 divided by ED50, defining the margin of safety between clinical benefit and dangerous toxicity.</desc><rect width="800" height="520" fill="#FFFFFF"/><text x="400" y="34" font-size="20" font-weight="700" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Therapeutic index and safety window</text><text x="400" y="56" font-size="12.5" font-weight="400" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Comparison of therapeutic response (ED50) and adverse toxic response (TD50)</text><line x1="140" y1="410" x2="680" y2="410" stroke="#071318" stroke-width="2"/><line x1="140" y1="410" x2="140" y2="120" stroke="#071318" stroke-width="2"/><rect x="310" y="130" width="200" height="280" fill="#EAF3F0" opacity="0.6"/><path d="M {' L '.join(pts_ed)}" fill="none" stroke="#0B6B5B" stroke-width="3.5"/><path d="M {' L '.join(pts_td)}" fill="none" stroke="#B42318" stroke-width="3.5"/><circle cx="310" cy="270" r="4" fill="#0B6B5B"/><line x1="310" y1="270" x2="310" y2="410" stroke="#0B6B5B" stroke-width="1.5" stroke-dasharray="3 3"/><text x="310" y="426" font-size="12" font-weight="700" text-anchor="middle" fill="#0B6B5B" font-family="system-ui,sans-serif">ED50</text><circle cx="510" cy="270" r="4" fill="#B42318"/><line x1="510" y1="270" x2="510" y2="410" stroke="#B42318" stroke-width="1.5" stroke-dasharray="3 3"/><text x="510" y="426" font-size="12" font-weight="700" text-anchor="middle" fill="#B42318" font-family="system-ui,sans-serif">TD50</text><line x1="310" y1="200" x2="510" y2="200" stroke="#071318" stroke-width="2"/><circle cx="310" cy="200" r="3" fill="#071318"/><circle cx="510" cy="200" r="3" fill="#071318"/><text x="410" y="190" font-size="13" font-weight="700" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Therapeutic window</text><text x="410" y="222" font-size="11.5" font-weight="600" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">TI = TD50 / ED50</text><text x="240" y="150" font-size="13" font-weight="700" fill="#0B6B5B" font-family="system-ui,sans-serif">Therapeutic response (efficacy)</text><text x="535" y="150" font-size="13" font-weight="700" fill="#B42318" font-family="system-ui,sans-serif">Toxic response (adverse effect)</text><rect x="540" y="240" width="180" height="75" rx="8" fill="#FBF8EE" stroke="#B7791F" stroke-width="1.5"/><text x="550" y="260" font-size="11" font-weight="700" fill="#B7791F" font-family="system-ui,sans-serif">Narrow Therapeutic Index:</text><text x="550" y="278" font-size="10.5" fill="#071318" font-family="system-ui,sans-serif">• Digoxin, Warfarin, Lithium</text><text x="550" y="294" font-size="10.5" fill="#071318" font-family="system-ui,sans-serif">• Phenytoin, Theophylline</text><text x="550" y="308" font-size="10" fill="#3D5A54" font-family="system-ui,sans-serif">(Requires drug level monitoring)</text><text x="410" y="455" font-size="13" font-weight="600" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Log Dose [mg/kg]</text><text x="90" y="265" font-size="13" font-weight="600" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif" transform="rotate(-90 90 265)">Percentage of individuals responding</text><text x="125" y="414" font-size="11" text-anchor="end" fill="#3D5A54" font-family="system-ui,sans-serif">0%</text><text x="125" y="274" font-size="11" text-anchor="end" fill="#3D5A54" font-family="system-ui,sans-serif">50%</text><text x="125" y="134" font-size="11" text-anchor="end" fill="#3D5A54" font-family="system-ui,sans-serif">100%</text><text x="400" y="505" font-size="11" font-weight="400" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">A larger therapeutic index represents a safer drug; narrow therapeutic index agents demand therapeutic drug monitoring.</text></svg>'''
    with open(os.path.join(OUT_DIR, "pharma-therapeutic-index.svg"), "w") as f:
        f.write(svg)

# 3. pharma-elimination-kinetics.svg
def gen_pharma_elimination_kinetics():
    # First-order: C(t) = 100 * exp(-0.693 * t / 2) (half-life = 2 hr)
    # Zero-order: C(t) = 100 - 12.5 * t (linear decline: 12.5 mg/L/hr)
    pts_first = [f"{160 + t * 50:.1f} {410 - 100 * math.exp(-0.693 * t / 2) * 2.8:.1f}" for t in [i * 0.2 for i in range(41)]]
    pts_zero = [f"{160 + t * 50:.1f} {410 - max(0, 100 - 12.5 * t) * 2.8:.1f}" for t in [i * 0.2 for i in range(41)]]

    svg = f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 520" role="img" aria-labelledby="t d"><title id="t">First-order versus zero-order elimination kinetics</title><desc id="d">Comparative plasma drug concentration decline curves over time. First-order elimination exhibits an exponential curve with constant half-life where a constant fraction is cleared per hour. Zero-order elimination displays a straight line where a constant amount is cleared per hour due to enzyme saturation.</desc><rect width="800" height="520" fill="#FFFFFF"/><text x="400" y="34" font-size="20" font-weight="700" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Drug elimination: First-order vs Zero-order</text><text x="400" y="56" font-size="12.5" font-weight="400" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Plasma concentration decay profiles and clearance mechanisms</text><line x1="160" y1="410" x2="660" y2="410" stroke="#071318" stroke-width="2"/><line x1="160" y1="410" x2="160" y2="120" stroke="#071318" stroke-width="2"/><path d="M {' L '.join(pts_first)}" fill="none" stroke="#0B6B5B" stroke-width="3.5"/><path d="M {' L '.join(pts_zero)}" fill="none" stroke="#B42318" stroke-width="3.5" stroke-dasharray="6 3"/><circle cx="{160 + 2*50}" cy="{410 - 50*2.8}" r="4" fill="#0B6B5B"/><line x1="{160 + 2*50}" y1="{410 - 50*2.8}" x2="{160 + 2*50}" y2="410" stroke="#0B6B5B" stroke-width="1" stroke-dasharray="3 3"/><text x="{160 + 2*50}" y="425" font-size="11" font-weight="700" text-anchor="middle" fill="#0B6B5B" font-family="system-ui,sans-serif">t½ = 2h</text><circle cx="{160 + 4*50}" cy="{410 - 25*2.8}" r="4" fill="#0B6B5B"/><line x1="{160 + 4*50}" y1="{410 - 25*2.8}" x2="{160 + 4*50}" y2="410" stroke="#0B6B5B" stroke-width="1" stroke-dasharray="3 3"/><text x="{160 + 4*50}" y="425" font-size="11" font-weight="700" text-anchor="middle" fill="#0B6B5B" font-family="system-ui,sans-serif">2× t½</text><rect x="420" y="140" width="220" height="90" rx="8" fill="#EAF3F0" stroke="#0B6B5B" stroke-width="1.5"/><text x="430" y="162" font-size="12.5" font-weight="700" fill="#0B6B5B" font-family="system-ui,sans-serif">First-Order Elimination (Most drugs)</text><text x="430" y="180" font-size="11" fill="#071318" font-family="system-ui,sans-serif">• Constant fraction (e.g. 50%) / unit time</text><text x="430" y="196" font-size="11" fill="#071318" font-family="system-ui,sans-serif">• Half-life (t½) is constant</text><text x="430" y="212" font-size="11" fill="#3D5A54" font-family="system-ui,sans-serif">• Rate = k · C (concentration-dependent)</text><rect x="420" y="250" width="220" height="90" rx="8" fill="#FDF2F0" stroke="#B42318" stroke-width="1.5"/><text x="430" y="272" font-size="12.5" font-weight="700" fill="#B42318" font-family="system-ui,sans-serif">Zero-Order Elimination (Saturable)</text><text x="430" y="290" font-size="11" fill="#071318" font-family="system-ui,sans-serif">• Constant amount (e.g. 10 mg) / unit time</text><text x="430" y="306" font-size="11" fill="#071318" font-family="system-ui,sans-serif">• Half-life increases with higher dose</text><text x="430" y="322" font-size="11" fill="#3D5A54" font-family="system-ui,sans-serif">• Phenytoin, Ethanol, Aspirin (high dose)</text><text x="410" y="450" font-size="13" font-weight="600" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Time [hours]</text><text x="95" y="265" font-size="13" font-weight="600" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif" transform="rotate(-90 95 265)">Plasma Concentration (mg/L)</text><text x="145" y="414" font-size="11" text-anchor="end" fill="#3D5A54" font-family="system-ui,sans-serif">0</text><text x="145" y="274" font-size="11" text-anchor="end" fill="#3D5A54" font-family="system-ui,sans-serif">50</text><text x="145" y="134" font-size="11" text-anchor="end" fill="#3D5A54" font-family="system-ui,sans-serif">100</text><text x="{160 + 0*50}" y="440" font-size="11" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">0</text><text x="{160 + 2*50}" y="440" font-size="11" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">2</text><text x="{160 + 4*50}" y="440" font-size="11" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">4</text><text x="{160 + 6*50}" y="440" font-size="11" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">6</text><text x="{160 + 8*50}" y="440" font-size="11" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">8</text><text x="400" y="505" font-size="11" font-weight="400" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">In first-order kinetics, 4 to 5 half-lives clear >95% of a drug; zero-order clearance enzymes are saturated at therapeutic levels.</text></svg>'''
    with open(os.path.join(OUT_DIR, "pharma-elimination-kinetics.svg"), "w") as f:
        f.write(svg)

# 4. micro-cell-wall.svg
def gen_micro_cell_wall():
    svg = '''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 520" role="img" aria-labelledby="t d"><title id="t">Bacterial cell wall: Gram-positive versus Gram-negative</title><desc id="d">Cross-sectional comparison of bacterial cell envelopes. Gram-positive bacteria feature a thick multilayered peptidoglycan mesh rich in lipoteichoic and teichoic acids above a single inner membrane. Gram-negative bacteria feature an outer lipid bilayer with lipopolysaccharide endotoxin and porins, a periplasmic space containing thin peptidoglycan, and an inner cytoplasmic membrane.</desc><rect width="800" height="520" fill="#FFFFFF"/><text x="400" y="34" font-size="20" font-weight="700" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Bacterial cell wall: Gram-positive vs Gram-negative</text><text x="400" y="56" font-size="12.5" font-weight="400" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Envelope architecture, peptidoglycan depth, and endotoxin localization</text><line x1="400" y1="80" x2="400" y2="460" stroke="#E0ECE8" stroke-width="2" stroke-dasharray="6 4"/><text x="210" y="100" font-size="16" font-weight="700" text-anchor="middle" fill="#0B6B5B" font-family="system-ui,sans-serif">Gram-Positive Envelope</text><text x="210" y="118" font-size="11.5" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Thick peptidoglycan (retains crystal violet)</text><rect x="60" y="140" width="300" height="150" rx="4" fill="#EAF3F0" stroke="#0B6B5B" stroke-width="2.5"/><text x="210" y="210" font-size="14" font-weight="700" text-anchor="middle" fill="#0B6B5B" font-family="system-ui,sans-serif">Thick Peptidoglycan (20–80 nm)</text><text x="210" y="230" font-size="11.5" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Multilayered murein cross-linked mesh</text><line x1="110" y1="130" x2="110" y2="350" stroke="#B7791F" stroke-width="4"/><circle cx="110" cy="126" r="6" fill="#B7791F"/><line x1="260" y1="130" x2="260" y2="290" stroke="#B7791F" stroke-width="3" stroke-dasharray="4 2"/><circle cx="260" cy="126" r="5" fill="#B7791F"/><text x="210" y="138" font-size="10.5" font-weight="700" fill="#B7791F" font-family="system-ui,sans-serif">Lipoteichoic &amp; Teichoic acids</text><rect x="60" y="330" width="300" height="40" rx="4" fill="#0B6B5B" stroke="#071318" stroke-width="1.5"/><text x="210" y="355" font-size="12" font-weight="600" text-anchor="middle" fill="#FFFFFF" font-family="system-ui,sans-serif">Inner Cytoplasmic Membrane</text><text x="210" y="420" font-size="11.5" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Stains deep violet / purple</text><text x="210" y="438" font-size="11" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">e.g. Staphylococcus, Streptococcus, Bacillus</text><text x="590" y="100" font-size="16" font-weight="700" text-anchor="middle" fill="#B42318" font-family="system-ui,sans-serif">Gram-Negative Envelope</text><text x="590" y="118" font-size="11.5" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Outer membrane + periplasm + thin peptidoglycan</text><rect x="440" y="140" width="300" height="35" rx="4" fill="#B42318" stroke="#071318" stroke-width="1.5"/><text x="590" y="162" font-size="12" font-weight="700" text-anchor="middle" fill="#FFFFFF" font-family="system-ui,sans-serif">Outer Membrane (LPS / Endotoxin)</text><line x1="470" y1="125" x2="470" y2="140" stroke="#B7791F" stroke-width="3"/><line x1="510" y1="125" x2="510" y2="140" stroke="#B7791F" stroke-width="3"/><line x1="670" y1="125" x2="670" y2="140" stroke="#B7791F" stroke-width="3"/><text x="590" y="132" font-size="10.5" font-weight="700" fill="#B7791F" font-family="system-ui,sans-serif">Lipid A + Core + O-antigen</text><rect x="580" y="140" width="20" height="35" fill="#EAF3F0" stroke="#071318" stroke-width="1"/><text x="590" y="190" font-size="10" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Porin channel</text><rect x="440" y="195" width="300" height="95" fill="#F4F8F6" stroke="#D0E2DB" stroke-width="1"/><text x="448" y="215" font-size="11" font-weight="700" fill="#0B6B5B" font-family="system-ui,sans-serif">Periplasmic space</text><rect x="450" y="235" width="280" height="20" rx="3" fill="#EAF3F0" stroke="#0B6B5B" stroke-width="2"/><text x="590" y="250" font-size="11.5" font-weight="700" text-anchor="middle" fill="#0B6B5B" font-family="system-ui,sans-serif">Thin Peptidoglycan (2–7 nm)</text><rect x="440" y="330" width="300" height="40" rx="4" fill="#0B6B5B" stroke="#071318" stroke-width="1.5"/><text x="590" y="355" font-size="12" font-weight="600" text-anchor="middle" fill="#FFFFFF" font-family="system-ui,sans-serif">Inner Cytoplasmic Membrane</text><text x="590" y="420" font-size="11.5" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Stains pink / red (counterstained by safranin)</text><text x="590" y="438" font-size="11" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">e.g. E. coli, Klebsiella, Pseudomonas, Neisseria</text><text x="400" y="505" font-size="11" font-weight="400" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Alcohol dissolves the lipid-rich Gram-negative outer membrane, washing out crystal violet; the dense Gram-positive mesh traps it.</text></svg>'''
    with open(os.path.join(OUT_DIR, "micro-cell-wall.svg"), "w") as f:
        f.write(svg)

# 5. micro-growth-curve.svg
def gen_micro_growth_curve():
    # Lag (x: 160 to 240, flat y=370)
    # Log (x: 240 to 420, steep sigmoid up to y=170)
    # Stationary (x: 420 to 560, plateau at y=170)
    # Decline (x: 560 to 660, decay down to y=330)
    pts = ["160.0 370.0", "200.0 370.0", "240.0 370.0"]
    for i in range(1, 21):
        x = 240 + i * 9.0
        pct = 1 / (1 + math.exp(-0.35 * (i - 10)))
        y = 370 - pct * 200
        pts.append(f"{x:.1f} {y:.1f}")
    pts.extend(["460.0 170.0", "500.0 170.0", "540.0 170.0", "560.0 170.0"])
    for i in range(1, 15):
        x = 560 + i * 7.14
        y = 170 + i * 11.4
        pts.append(f"{x:.1f} {y:.1f}")

    svg = f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 520" role="img" aria-labelledby="t d"><title id="t">Bacterial growth curve in batch culture</title><desc id="d">The four phases of bacterial growth plotted as log viable cell count against time: 1. Lag phase with metabolic adaptation and no division; 2. Log or exponential phase with maximum balanced division and antibiotic sensitivity; 3. Stationary phase where growth equals death; 4. Decline or death phase with exponential viability loss.</desc><rect width="800" height="520" fill="#FFFFFF"/><text x="400" y="34" font-size="20" font-weight="700" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Bacterial growth curve: Four phases</text><text x="400" y="56" font-size="12.5" font-weight="400" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Log viable count over time in closed batch culture</text><line x1="140" y1="410" x2="680" y2="410" stroke="#071318" stroke-width="2"/><line x1="140" y1="410" x2="140" y2="120" stroke="#071318" stroke-width="2"/><line x1="240" y1="120" x2="240" y2="410" stroke="#E0ECE8" stroke-width="1.5" stroke-dasharray="4 4"/><line x1="420" y1="120" x2="420" y2="410" stroke="#E0ECE8" stroke-width="1.5" stroke-dasharray="4 4"/><line x1="560" y1="120" x2="560" y2="410" stroke="#E0ECE8" stroke-width="1.5" stroke-dasharray="4 4"/><path d="M {' L '.join(pts)}" fill="none" stroke="#0B6B5B" stroke-width="3.5"/><text x="190" y="140" font-size="13" font-weight="700" text-anchor="middle" fill="#0B6B5B" font-family="system-ui,sans-serif">1. Lag Phase</text><text x="190" y="158" font-size="11" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Enzyme adaptation</text><text x="190" y="172" font-size="10.5" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">No cell division</text><text x="330" y="140" font-size="13" font-weight="700" text-anchor="middle" fill="#B7791F" font-family="system-ui,sans-serif">2. Log (Exponential)</text><text x="330" y="158" font-size="11" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Constant doubling time</text><text x="330" y="172" font-size="10.5" font-weight="700" text-anchor="middle" fill="#B7791F" font-family="system-ui,sans-serif">Max antibiotic killing</text><text x="490" y="140" font-size="13" font-weight="700" text-anchor="middle" fill="#0B6B5B" font-family="system-ui,sans-serif">3. Stationary</text><text x="490" y="158" font-size="11" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Growth = Death</text><text x="490" y="172" font-size="10.5" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Spore / toxin release</text><text x="615" y="140" font-size="13" font-weight="700" text-anchor="middle" fill="#B42318" font-family="system-ui,sans-serif">4. Decline / Death</text><text x="615" y="158" font-size="11" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Death exceeds division</text><text x="615" y="172" font-size="10.5" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Involution forms</text><text x="410" y="445" font-size="13" font-weight="600" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Time in Culture</text><text x="95" y="265" font-size="13" font-weight="600" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif" transform="rotate(-90 95 265)">Log Number of Viable Bacteria</text><text x="400" y="505" font-size="11" font-weight="400" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Beta-lactam antibiotics and aminoglycosides exert maximum bactericidal efficacy during the active log phase.</text></svg>'''
    with open(os.path.join(OUT_DIR, "micro-growth-curve.svg"), "w") as f:
        f.write(svg)

# 6. micro-antibody-response.svg
def gen_micro_antibody_response():
    # Primary exposure at day 0 (x=160).
    # IgM rises from day 5 to 12 (peak 60), then drops to 10 by day 28.
    # IgG rises from day 10 to 18 (peak 80), then slowly declines to 20 by day 35.
    # Secondary exposure at day 40 (x=440).
    # IgM minor rise to 50.
    # IgG rapid steep rise from day 42 to 48 (peak 280), lasting long.
    svg = '''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 520" role="img" aria-labelledby="t d"><title id="t">Primary versus secondary antibody response</title><desc id="d">Serum antibody titre comparison following initial antigen exposure versus secondary booster exposure. The primary response features a 5 to 7 day lag with modest IgM preceding IgG. The secondary response displays a brief 1 to 3 day lag, massive high-affinity IgG production driven by memory B cells, and persistent protective titre.</desc><rect width="800" height="520" fill="#FFFFFF"/><text x="400" y="34" font-size="20" font-weight="700" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Primary versus secondary humoral immune response</text><text x="400" y="56" font-size="12.5" font-weight="400" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Kinetics, lag phase, and isotype switching from IgM to high-affinity IgG</text><line x1="140" y1="410" x2="700" y2="410" stroke="#071318" stroke-width="2"/><line x1="140" y1="410" x2="140" y2="120" stroke="#071318" stroke-width="2"/><line x1="180" y1="360" x2="180" y2="410" stroke="#071318" stroke-width="2" marker-end="url(#arr-dn)"/><text x="180" y="350" font-size="11.5" font-weight="700" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Primary antigen</text><line x1="440" y1="360" x2="440" y2="410" stroke="#071318" stroke-width="2" marker-end="url(#arr-dn)"/><text x="440" y="350" font-size="11.5" font-weight="700" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Secondary booster</text><defs><marker id="arr-dn" viewBox="0 0 6 6" refX="3" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0 L3 6 L6 0 z" fill="#071318"/></marker></defs><path d="M 180 410 Q 210 410 230 360 Q 250 310 270 330 Q 310 370 360 405" fill="none" stroke="#B7791F" stroke-width="2.5" stroke-dasharray="5 3"/><path d="M 180 410 Q 230 410 260 350 Q 280 290 310 300 Q 360 330 420 390" fill="none" stroke="#0B6B5B" stroke-width="3"/><text x="250" y="315" font-size="11" font-weight="700" fill="#B7791F" font-family="system-ui,sans-serif">Primary IgM</text><text x="310" y="280" font-size="11.5" font-weight="700" fill="#0B6B5B" font-family="system-ui,sans-serif">Primary IgG</text><rect x="180" y="160" width="180" height="70" rx="6" fill="#F4F8F6" stroke="#0B6B5B" stroke-width="1.2"/><text x="190" y="180" font-size="11.5" font-weight="700" fill="#0B6B5B" font-family="system-ui,sans-serif">Primary Response:</text><text x="190" y="196" font-size="10.5" fill="#071318" font-family="system-ui,sans-serif">• Lag: 5–7 days (naive B cells)</text><text x="190" y="210" font-size="10.5" fill="#071318" font-family="system-ui,sans-serif">• IgM appears before IgG</text><text x="190" y="224" font-size="10.5" fill="#3D5A54" font-family="system-ui,sans-serif">• Lower peak titre &amp; lower affinity</text><path d="M 440 410 Q 455 410 470 365 Q 490 335 520 375 Q 560 400 600 408" fill="none" stroke="#B7791F" stroke-width="2.5" stroke-dasharray="5 3"/><path d="M 440 410 Q 455 405 470 230 Q 485 130 520 145 Q 600 170 680 220" fill="none" stroke="#0B6B5B" stroke-width="3.5"/><text x="495" y="340" font-size="11" font-weight="700" fill="#B7791F" font-family="system-ui,sans-serif">Secondary IgM</text><text x="535" y="140" font-size="14" font-weight="700" fill="#0B6B5B" font-family="system-ui,sans-serif">Secondary IgG (High affinity)</text><rect x="460" y="220" width="200" height="70" rx="6" fill="#EAF3F0" stroke="#0B6B5B" stroke-width="1.2"/><text x="470" y="240" font-size="11.5" font-weight="700" fill="#0B6B5B" font-family="system-ui,sans-serif">Secondary Response:</text><text x="470" y="256" font-size="10.5" fill="#071318" font-family="system-ui,sans-serif">• Short lag: 1–3 days (Memory B)</text><text x="470" y="270" font-size="10.5" fill="#071318" font-family="system-ui,sans-serif">• Dominated by high-titre IgG</text><text x="470" y="284" font-size="10.5" fill="#3D5A54" font-family="system-ui,sans-serif">• Somatic hypermutation &amp; affinity maturation</text><text x="410" y="445" font-size="13" font-weight="600" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Time [Weeks]</text><text x="95" y="265" font-size="13" font-weight="600" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif" transform="rotate(-90 95 265)">Serum Antibody Titre (log scale)</text><text x="400" y="505" font-size="11" font-weight="400" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Memory B cells and follicular helper T cells drive rapid isotype-switched, high-affinity IgG production on re-exposure.</text></svg>'''
    with open(os.path.join(OUT_DIR, "micro-antibody-response.svg"), "w") as f:
        f.write(svg)

# 7. path-extravasation.svg
def gen_path_extravasation():
    svg = '''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 520" role="img" aria-labelledby="t d"><title id="t">Leukocyte extravasation sequence in acute inflammation</title><desc id="d">Stepwise cascade of neutrophil recruitment from vascular lumen into inflamed interstitial tissue: 1. Margination and rolling mediated by endothelial E-selectin and P-selectin; 2. Activation and firm adhesion via neutrophil integrins LFA-1 and Mac-1 binding ICAM-1; 3. Diapedesis and transmigration through junctions mediated by PECAM-1 CD31; 4. Chemotaxis along gradient toward C5a, LTB4, IL-8, and bacterial peptides.</desc><rect width="800" height="520" fill="#FFFFFF"/><text x="400" y="34" font-size="20" font-weight="700" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Leukocyte extravasation cascade</text><text x="400" y="56" font-size="12.5" font-weight="400" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Four sequential steps: Margination, Rolling, Firm Adhesion, and Diapedesis</text><rect x="60" y="90" width="680" height="150" fill="#FDF5F4" stroke="#E8A09A" stroke-width="1.5"/><text x="75" y="115" font-size="12" font-weight="700" fill="#B42318" font-family="system-ui,sans-serif">Vascular Lumen (Blood flow →)</text><rect x="60" y="240" width="680" height="30" fill="#EAF3F0" stroke="#0B6B5B" stroke-width="2"/><text x="75" y="260" font-size="11" font-weight="700" fill="#0B6B5B" font-family="system-ui,sans-serif">Endothelial Monolayer</text><rect x="60" y="270" width="680" height="160" fill="#FAFBFB" stroke="#D0E2DB" stroke-width="1.5"/><text x="75" y="295" font-size="12" font-weight="700" fill="#3D5A54" font-family="system-ui,sans-serif">Extravascular Interstitial Tissue</text><circle cx="140" cy="170" r="28" fill="#FFFFFF" stroke="#0B6B5B" stroke-width="2.5"/><text x="140" y="174" font-size="10" font-weight="700" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">PMN</text><text x="140" y="222" font-size="11" font-weight="700" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">1. Margination</text><text x="140" y="325" font-size="10.5" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Stasis pushes</text><text x="140" y="340" font-size="10.5" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">cells to periphery</text><circle cx="300" cy="190" r="28" fill="#FFFFFF" stroke="#B7791F" stroke-width="2.5"/><text x="300" y="194" font-size="10" font-weight="700" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">PMN</text><text x="300" y="232" font-size="11" font-weight="700" text-anchor="middle" fill="#B7791F" font-family="system-ui,sans-serif">2. Rolling</text><text x="300" y="325" font-size="11" font-weight="700" text-anchor="middle" fill="#B7791F" font-family="system-ui,sans-serif">Selectins</text><text x="300" y="342" font-size="10" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">E- &amp; P-selectin bind</text><text x="300" y="356" font-size="10" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Sialyl-Lewis X</text><circle cx="470" cy="225" r="28" fill="#FFFFFF" stroke="#0B6B5B" stroke-width="3"/><text x="470" y="229" font-size="10" font-weight="700" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">PMN</text><text x="470" y="270" font-size="11" font-weight="700" text-anchor="middle" fill="#0B6B5B" font-family="system-ui,sans-serif">3. Adhesion</text><text x="470" y="325" font-size="11" font-weight="700" text-anchor="middle" fill="#0B6B5B" font-family="system-ui,sans-serif">Integrins</text><text x="470" y="342" font-size="10" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">LFA-1, Mac-1 bind</text><text x="470" y="356" font-size="10" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">ICAM-1 &amp; VCAM-1</text><ellipse cx="640" cy="265" rx="20" ry="32" fill="#FFFFFF" stroke="#B42318" stroke-width="2.5"/><text x="640" y="269" font-size="9" font-weight="700" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">PMN</text><text x="640" y="318" font-size="11" font-weight="700" text-anchor="middle" fill="#B42318" font-family="system-ui,sans-serif">4. Diapedesis</text><text x="640" y="340" font-size="11" font-weight="700" text-anchor="middle" fill="#B42318" font-family="system-ui,sans-serif">PECAM-1 (CD31)</text><text x="640" y="356" font-size="10" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Transmigration to</text><text x="640" y="370" font-size="10" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">C5a, LTB4, IL-8</text><line x1="170" y1="170" x2="260" y2="185" stroke="#071318" stroke-width="1.5" marker-end="url(#arr-bl)"/> <line x1="335" y1="195" x2="430" y2="215" stroke="#071318" stroke-width="1.5" marker-end="url(#arr-bl)"/> <line x1="505" y1="225" x2="605" y2="255" stroke="#071318" stroke-width="1.5" marker-end="url(#arr-bl)"/><defs><marker id="arr-bl" viewBox="0 0 6 6" refX="5" refY="3" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0 L6 3 L0 6 z" fill="#071318"/></marker></defs><text x="400" y="465" font-size="12" font-weight="700" text-anchor="middle" fill="#B42318" font-family="system-ui,sans-serif">Chemotactic gradient: C5a · Leukotriene B4 (LTB4) · Interleukin-8 (IL-8) · Bacterial N-formyl peptides</text><text x="400" y="505" font-size="11" font-weight="400" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Defective integrin CD18 causes Leukocyte Adhesion Deficiency type 1 (LAD-1) with delayed umbilical cord separation.</text></svg>'''
    with open(os.path.join(OUT_DIR, "path-extravasation.svg"), "w") as f:
        f.write(svg)

# 8. path-apoptosis-pathways.svg
def gen_path_apoptosis_pathways():
    svg = '''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 520" role="img" aria-labelledby="t d"><title id="t">Apoptosis pathways: intrinsic versus extrinsic</title><desc id="d">Diagram illustrating the two initiating pathways of programmed cell death. The intrinsic mitochondrial pathway is triggered by DNA damage, reactive oxygen species, and growth factor withdrawal, causing Bax and Bak pore formation, cytochrome c release, and caspase 9 activation. The extrinsic death receptor pathway is triggered by Fas ligand or TNF binding, activating caspase 8. Both converge on executioner caspases 3, 6, and 7.</desc><rect width="800" height="520" fill="#FFFFFF"/><text x="400" y="34" font-size="20" font-weight="700" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Apoptosis: Intrinsic versus Extrinsic pathways</text><text x="400" y="56" font-size="12.5" font-weight="400" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Initiating triggers, caspase cascades, and convergence on executioner enzymes</text><rect x="60" y="85" width="310" height="235" rx="8" fill="#EAF3F0" stroke="#0B6B5B" stroke-width="2"/><text x="215" y="110" font-size="14.5" font-weight="700" text-anchor="middle" fill="#0B6B5B" font-family="system-ui,sans-serif">Intrinsic (Mitochondrial) Pathway</text><text x="215" y="130" font-size="11" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">DNA damage (p53) · Hypoxia · Misfolded proteins</text><text x="215" y="152" font-size="12" font-weight="700" text-anchor="middle" fill="#B42318" font-family="system-ui,sans-serif">BAX &amp; BAK activation</text><text x="215" y="168" font-size="10.5" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">(Inhibited by anti-apoptotic BCL-2 &amp; BCL-XL)</text><line x1="215" y1="175" x2="215" y2="195" stroke="#0B6B5B" stroke-width="2" marker-end="url(#arr-teal)"/><rect x="110" y="198" width="210" height="30" rx="4" fill="#FFFFFF" stroke="#0B6B5B" stroke-width="1.5"/><text x="215" y="218" font-size="12" font-weight="700" text-anchor="middle" fill="#0B6B5B" font-family="system-ui,sans-serif">Cytochrome c + Apaf-1 release</text><line x1="215" y1="230" x2="215" y2="250" stroke="#0B6B5B" stroke-width="2" marker-end="url(#arr-teal)"/><rect x="130" y="255" width="170" height="36" rx="4" fill="#0B6B5B"/><text x="215" y="278" font-size="13" font-weight="700" text-anchor="middle" fill="#FFFFFF" font-family="system-ui,sans-serif">Caspase-9 (Initiator)</text><rect x="430" y="85" width="310" height="235" rx="8" fill="#FDF2F0" stroke="#B42318" stroke-width="2"/><text x="585" y="110" font-size="14.5" font-weight="700" text-anchor="middle" fill="#B42318" font-family="system-ui,sans-serif">Extrinsic (Death Receptor) Pathway</text><text x="585" y="130" font-size="11" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">FasL binding Fas (CD95) · TNF-α binding TNFR1</text><line x1="585" y1="145" x2="585" y2="175" stroke="#B42318" stroke-width="2" marker-end="url(#arr-red)"/><rect x="480" y="178" width="210" height="46" rx="4" fill="#FFFFFF" stroke="#B42318" stroke-width="1.5"/><text x="585" y="198" font-size="12" font-weight="700" text-anchor="middle" fill="#B42318" font-family="system-ui,sans-serif">Receptor Trimerization + FADD</text><text x="585" y="214" font-size="10.5" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Death domain adaptor recruitment</text><line x1="585" y1="228" x2="585" y2="250" stroke="#B42318" stroke-width="2" marker-end="url(#arr-red)"/><rect x="495" y="255" width="180" height="36" rx="4" fill="#B42318"/><text x="585" y="278" font-size="13" font-weight="700" text-anchor="middle" fill="#FFFFFF" font-family="system-ui,sans-serif">Caspase-8 &amp; 10 (Initiator)</text><line x1="215" y1="295" x2="350" y2="355" stroke="#0B6B5B" stroke-width="2.5" marker-end="url(#arr-teal)"/><line x1="585" y1="295" x2="450" y2="355" stroke="#B42318" stroke-width="2.5" marker-end="url(#arr-red)"/><defs><marker id="arr-teal" viewBox="0 0 6 6" refX="5" refY="3" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0 L6 3 L0 6 z" fill="#0B6B5B"/></marker><marker id="arr-red" viewBox="0 0 6 6" refX="5" refY="3" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0 L6 3 L0 6 z" fill="#B42318"/></marker></defs><rect x="250" y="360" width="300" height="50" rx="6" fill="#071318"/><text x="400" y="385" font-size="15" font-weight="700" text-anchor="middle" fill="#FFFFFF" font-family="system-ui,sans-serif">Executioner Caspases: 3, 6 &amp; 7</text><text x="400" y="401" font-size="11" text-anchor="middle" fill="#EAF3F0" font-family="system-ui,sans-serif">Cleave structural proteins &amp; activate endonucleases</text><line x1="400" y1="412" x2="400" y2="435" stroke="#071318" stroke-width="2" marker-end="url(#arr-bl)"/><text x="400" y="455" font-size="13" font-weight="700" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Apoptotic Bodies → Phagocytosis without inflammation</text><text x="400" y="505" font-size="11" font-weight="400" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">BCL-2 overexpression in follicular lymphoma (t(14;18)) inhibits the intrinsic apoptotic pathway, preventing cell death.</text></svg>'''
    with open(os.path.join(OUT_DIR, "path-apoptosis-pathways.svg"), "w") as f:
        f.write(svg)

# 9. path-granuloma.svg
def gen_path_granuloma():
    svg = '''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 520" role="img" aria-labelledby="t d"><title id="t">Structure of an epithelioid granuloma</title><desc id="d">Concentric architecture of a chronic tuberculous granuloma. Center contains acellular eosinophilic caseous necrosis, surrounded by modified epithelioid macrophages and multinucleated horseshoe-shaped Langhans giant cells, enclosed by a peripheral lymphocytic cuff of CD4 T cells and fibroblasts.</desc><rect width="800" height="520" fill="#FFFFFF"/><text x="400" y="34" font-size="20" font-weight="700" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Architecture of a caseating granuloma</text><text x="400" y="56" font-size="12.5" font-weight="400" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Concentric organisation in chronic mycobacterial and fungal infection</text><circle cx="340" cy="270" r="190" fill="#F4F8F6" stroke="#0B6B5B" stroke-width="2"/><circle cx="340" cy="270" r="135" fill="#EAF3F0" stroke="#0B6B5B" stroke-width="2" stroke-dasharray="4 2"/><circle cx="340" cy="270" r="65" fill="#FDF2F0" stroke="#B42318" stroke-width="2"/><text x="340" y="265" font-size="13" font-weight="700" text-anchor="middle" fill="#B42318" font-family="system-ui,sans-serif">Central Caseous</text><text x="340" y="282" font-size="12" font-weight="700" text-anchor="middle" fill="#B42318" font-family="system-ui,sans-serif">Necrosis</text><circle cx="280" cy="180" r="16" fill="#FFFFFF" stroke="#0B6B5B" stroke-width="1.8"/><circle cx="380" cy="170" r="18" fill="#FFFFFF" stroke="#0B6B5B" stroke-width="1.8"/><circle cx="430" cy="250" r="16" fill="#FFFFFF" stroke="#0B6B5B" stroke-width="1.8"/><circle cx="250" cy="310" r="17" fill="#FFFFFF" stroke="#0B6B5B" stroke-width="1.8"/><path d="M 290 350 C 290 330, 350 330, 350 350 C 350 370, 290 370, 290 350 Z" fill="#FFFFFF" stroke="#B7791F" stroke-width="2.5"/><circle cx="298" cy="342" r="2.5" fill="#B7791F"/><circle cx="308" cy="336" r="2.5" fill="#B7791F"/><circle cx="320" cy="334" r="2.5" fill="#B7791F"/><circle cx="332" cy="336" r="2.5" fill="#B7791F"/><circle cx="342" cy="342" r="2.5" fill="#B7791F"/><rect x="560" y="110" width="200" height="65" rx="6" fill="#FDF2F0" stroke="#B42318" stroke-width="1.5"/><text x="570" y="130" font-size="12" font-weight="700" fill="#B42318" font-family="system-ui,sans-serif">1. Central Necrosis</text><text x="570" y="146" font-size="10.5" fill="#071318" font-family="system-ui,sans-serif">Cheesy, acellular debris</text><text x="570" y="160" font-size="10.5" fill="#3D5A54" font-family="system-ui,sans-serif">Loss of cell outlines</text><rect x="560" y="185" width="200" height="65" rx="6" fill="#EAF3F0" stroke="#0B6B5B" stroke-width="1.5"/><text x="570" y="205" font-size="12" font-weight="700" fill="#0B6B5B" font-family="system-ui,sans-serif">2. Epithelioid Cells</text><text x="570" y="221" font-size="10.5" fill="#071318" font-family="system-ui,sans-serif">Activated macrophages</text><text x="570" y="235" font-size="10.5" fill="#3D5A54" font-family="system-ui,sans-serif">Abundant pink cytoplasm</text><rect x="560" y="260" width="200" height="75" rx="6" fill="#FBF8EE" stroke="#B7791F" stroke-width="1.5"/><text x="570" y="280" font-size="12" font-weight="700" fill="#B7791F" font-family="system-ui,sans-serif">3. Langhans Giant Cells</text><text x="570" y="296" font-size="10.5" fill="#071318" font-family="system-ui,sans-serif">Fused macrophages</text><text x="570" y="310" font-size="10.5" fill="#3D5A54" font-family="system-ui,sans-serif">Horseshoe nuclei rim</text><rect x="560" y="345" width="200" height="75" rx="6" fill="#F4F8F6" stroke="#0B6B5B" stroke-width="1.5"/><text x="570" y="365" font-size="12" font-weight="700" fill="#0B6B5B" font-family="system-ui,sans-serif">4. Lymphocytic Cuff</text><text x="570" y="381" font-size="10.5" fill="#071318" font-family="system-ui,sans-serif">CD4+ Th1 T-cells (IFN-γ)</text><text x="570" y="395" font-size="10.5" fill="#3D5A54" font-family="system-ui,sans-serif">Surrounding rim of fibroblasts</text><line x1="395" y1="270" x2="560" y2="145" stroke="#B42318" stroke-width="1" stroke-dasharray="3 3"/><line x1="435" y1="235" x2="560" y2="215" stroke="#0B6B5B" stroke-width="1" stroke-dasharray="3 3"/><line x1="355" y1="355" x2="560" y2="300" stroke="#B7791F" stroke-width="1" stroke-dasharray="3 3"/><line x1="495" y1="365" x2="560" y2="375" stroke="#0B6B5B" stroke-width="1" stroke-dasharray="3 3"/><text x="400" y="505" font-size="11" font-weight="400" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Activated macrophages secrete TNF-alpha, which maintains granuloma stability; anti-TNF biologics carry risk of TB reactivation.</text></svg>'''
    with open(os.path.join(OUT_DIR, "path-granuloma.svg"), "w") as f:
        f.write(svg)

# 10. bio-lineweaver-burk.svg
def gen_bio_lineweaver_burk():
    # 1/V vs 1/[S]
    # Center origin at x=340, y=360
    # X-axis: -1/Km to +1/[S], range x=120 to 660
    # Y-axis: 0 to 1/V, range y=380 to 120
    # Uninhibited: passes through (-1/Km = -1.5, x=220) and (1/Vmax = 1.0, y=260)
    # Competitive: same 1/Vmax (y=260 at x=340), but -1/Km shifts closer to 0 (-0.8, x=276)
    # Non-competitive: same -1/Km (x=220 at y=360), but 1/Vmax is higher (y=180 at x=340)
    svg = '''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 520" role="img" aria-labelledby="t d"><title id="t">Lineweaver-Burk double reciprocal enzyme plot</title><desc id="d">Lineweaver-Burk plot of 1/V versus 1/[S]. The uninhibited enzyme line crosses the Y-axis at 1/Vmax and X-axis at -1/Km. Competitive inhibition intersects at the same Y-axis point (unchanged Vmax) with an increased apparent Km. Non-competitive inhibition intersects at the same X-axis point (unchanged Km) with a depressed Vmax indicated by a higher Y-intercept.</desc><rect width="800" height="520" fill="#FFFFFF"/><text x="400" y="34" font-size="20" font-weight="700" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Lineweaver-Burk plot: Enzyme inhibition</text><text x="400" y="56" font-size="12.5" font-weight="400" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Double-reciprocal plot (1/V versus 1/[S]) defining Km and Vmax</text><line x1="120" y1="360" x2="660" y2="360" stroke="#071318" stroke-width="2"/><line x1="340" y1="380" x2="340" y2="120" stroke="#071318" stroke-width="2"/><line x1="160" y1="410" x2="520" y2="110" stroke="#0B6B5B" stroke-width="3.5"/><line x1="228" y1="410" x2="480" y2="110" stroke="#B7791F" stroke-width="3" stroke-dasharray="6 3"/><line x1="170" y1="410" x2="440" y2="100" stroke="#B42318" stroke-width="3"/><circle cx="340" cy="260" r="5" fill="#0B6B5B"/><text x="325" y="264" font-size="11.5" font-weight="700" text-anchor="end" fill="#0B6B5B" font-family="system-ui,sans-serif">1 / Vmax</text><circle cx="220" cy="360" r="4.5" fill="#0B6B5B"/><text x="210" y="380" font-size="11" font-weight="700" text-anchor="middle" fill="#0B6B5B" font-family="system-ui,sans-serif">−1 / Km</text><circle cx="270" cy="360" r="4.5" fill="#B7791F"/><text x="280" y="392" font-size="11" font-weight="700" text-anchor="middle" fill="#B7791F" font-family="system-ui,sans-serif">−1 / Km'</text><circle cx="340" cy="190" r="5" fill="#B42318"/><text x="325" y="194" font-size="11.5" font-weight="700" text-anchor="end" fill="#B42318" font-family="system-ui,sans-serif">1 / Vmax'</text><rect x="490" y="140" width="240" height="80" rx="6" fill="#EAF3F0" stroke="#0B6B5B" stroke-width="1.5"/><text x="500" y="162" font-size="12.5" font-weight="700" fill="#0B6B5B" font-family="system-ui,sans-serif">Uninhibited Enzyme</text><text x="500" y="180" font-size="11" fill="#071318" font-family="system-ui,sans-serif">• Y-intercept = 1 / Vmax</text><text x="500" y="196" font-size="11" fill="#071318" font-family="system-ui,sans-serif">• X-intercept = −1 / Km</text><text x="500" y="212" font-size="11" fill="#3D5A54" font-family="system-ui,sans-serif">• Slope = Km / Vmax</text><rect x="490" y="230" width="240" height="75" rx="6" fill="#FBF8EE" stroke="#B7791F" stroke-width="1.5"/><text x="500" y="250" font-size="12.5" font-weight="700" fill="#B7791F" font-family="system-ui,sans-serif">Competitive Inhibition</text><text x="500" y="268" font-size="11" fill="#071318" font-family="system-ui,sans-serif">• Same Y-intercept (Same Vmax)</text><text x="500" y="284" font-size="11" fill="#071318" font-family="system-ui,sans-serif">• X-intercept moves right (Increased Km)</text><text x="500" y="298" font-size="10.5" fill="#3D5A54" font-family="system-ui,sans-serif">• Overcome by adding more substrate</text><rect x="490" y="315" width="240" height="75" rx="6" fill="#FDF2F0" stroke="#B42318" stroke-width="1.5"/><text x="500" y="335" font-size="12.5" font-weight="700" fill="#B42318" font-family="system-ui,sans-serif">Non-Competitive Inhibition</text><text x="500" y="353" font-size="11" fill="#071318" font-family="system-ui,sans-serif">• Same X-intercept (Same Km)</text><text x="500" y="369" font-size="11" fill="#071318" font-family="system-ui,sans-serif">• Higher Y-intercept (Decreased Vmax)</text><text x="500" y="383" font-size="10.5" fill="#3D5A54" font-family="system-ui,sans-serif">• Binds allosteric site; cannot be overcome</text><text x="410" y="440" font-size="13" font-weight="600" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">1 / [Substrate] (1 / mM)</text><text x="290" y="140" font-size="13" font-weight="600" text-anchor="end" fill="#071318" font-family="system-ui,sans-serif">1 / Velocity</text><text x="400" y="505" font-size="11" font-weight="400" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Statins are competitive HMG-CoA reductase inhibitors (Km increases); non-competitive inhibitors lower Vmax without affecting Km.</text></svg>'''
    with open(os.path.join(OUT_DIR, "bio-lineweaver-burk.svg"), "w") as f:
        f.write(svg)

# 11. bio-glycolysis-tca.svg
def gen_bio_glycolysis_tca():
    svg = '''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 520" role="img" aria-labelledby="t d"><title id="t">Central cellular energy metabolism hub</title><desc id="d">Metabolic pathway map connecting cytoplasmic glycolysis to mitochondrial respiration. Glucose converts to pyruvate yielding 2 ATP and 2 NADH. Under aerobic conditions pyruvate dehydrogenase generates Acetyl-CoA. Acetyl-CoA fuels the Krebs citric acid cycle generating 3 NADH, 1 FADH2, and 1 GTP per turn, driving oxidative phosphorylation to yield approximately 30 to 32 ATP.</desc><rect width="800" height="520" fill="#FFFFFF"/><text x="400" y="34" font-size="20" font-weight="700" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Central carbohydrate and energy metabolism</text><text x="400" y="56" font-size="12.5" font-weight="400" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Cytoplasmic glycolysis, pyruvate dehydrogenase, and mitochondrial citric acid cycle</text><rect x="60" y="85" width="680" height="110" rx="8" fill="#F4F8F6" stroke="#0B6B5B" stroke-width="1.8"/><text x="80" y="108" font-size="13" font-weight="700" fill="#0B6B5B" font-family="system-ui,sans-serif">Cytoplasm: Glycolysis</text><rect x="80" y="125" width="100" height="36" rx="4" fill="#FFFFFF" stroke="#0B6B5B" stroke-width="1.5"/><text x="130" y="148" font-size="12" font-weight="700" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Glucose (6C)</text><line x1="180" y1="143" x2="250" y2="143" stroke="#0B6B5B" stroke-width="2" marker-end="url(#arr-teal)"/><rect x="250" y="125" width="130" height="36" rx="4" fill="#FFFFFF" stroke="#0B6B5B" stroke-width="1.5"/><text x="315" y="148" font-size="11.5" font-weight="700" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Fructose-1,6-BP</text><text x="215" y="135" font-size="10" font-weight="700" text-anchor="middle" fill="#B42318" font-family="system-ui,sans-serif">PFK-1 (Rate-limiting)</text><line x1="380" y1="143" x2="450" y2="143" stroke="#0B6B5B" stroke-width="2" marker-end="url(#arr-teal)"/><rect x="450" y="125" width="120" height="36" rx="4" fill="#FFFFFF" stroke="#0B6B5B" stroke-width="1.5"/><text x="510" y="148" font-size="12" font-weight="700" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">2 × Pyruvate (3C)</text><text x="635" y="135" font-size="11" font-weight="700" fill="#0B6B5B" font-family="system-ui,sans-serif">Net Yield:</text><text x="635" y="152" font-size="10.5" fill="#071318" font-family="system-ui,sans-serif">2 ATP + 2 NADH</text><rect x="60" y="210" width="680" height="230" rx="8" fill="#EAF3F0" stroke="#0B6B5B" stroke-width="2"/><text x="80" y="235" font-size="13" font-weight="700" fill="#0B6B5B" font-family="system-ui,sans-serif">Mitochondrial Matrix: Pyruvate Dehydrogenase &amp; TCA Cycle</text><line x1="510" y1="161" x2="510" y2="245" stroke="#0B6B5B" stroke-width="2.5" marker-end="url(#arr-teal)"/><text x="525" y="210" font-size="11" font-weight="700" fill="#B7791F" font-family="system-ui,sans-serif">PDH Complex</text><text x="525" y="224" font-size="9.5" fill="#3D5A54" font-family="system-ui,sans-serif">(Requires B1, B2, B3, B5, Lipoic acid)</text><rect x="440" y="250" width="140" height="36" rx="4" fill="#FFFFFF" stroke="#B7791F" stroke-width="2"/><text x="510" y="273" font-size="12" font-weight="700" text-anchor="middle" fill="#B7791F" font-family="system-ui,sans-serif">Acetyl-CoA (2C)</text><circle cx="280" cy="335" r="70" fill="#FFFFFF" stroke="#0B6B5B" stroke-width="2.5"/><text x="280" y="325" font-size="13" font-weight="700" text-anchor="middle" fill="#0B6B5B" font-family="system-ui,sans-serif">Krebs Cycle</text><text x="280" y="342" font-size="11" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">(Citric Acid / TCA)</text><line x1="440" y1="270" x2="350" y2="300" stroke="#0B6B5B" stroke-width="2" marker-end="url(#arr-teal)"/><text x="390" y="318" font-size="10.5" font-weight="700" fill="#0B6B5B" font-family="system-ui,sans-serif">+ Oxaloacetate (4C)</text><text x="280" y="280" font-size="10" font-weight="700" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Citrate (6C)</text><text x="185" y="340" font-size="10" font-weight="700" fill="#071318" font-family="system-ui,sans-serif">α-Ketoglutarate</text><text x="280" y="420" font-size="10" font-weight="700" text-anchor="middle" fill="#071318" font-family="system-ui,sans-serif">Succinyl-CoA → Malate</text><rect x="440" y="315" width="260" height="95" rx="6" fill="#FFFFFF" stroke="#0B6B5B" stroke-width="1.5"/><text x="455" y="338" font-size="12" font-weight="700" fill="#0B6B5B" font-family="system-ui,sans-serif">TCA Cycle Yield (per Acetyl-CoA):</text><text x="455" y="358" font-size="11" fill="#071318" font-family="system-ui,sans-serif">• 3 NADH + 1 FADH₂</text><text x="455" y="374" font-size="11" fill="#071318" font-family="system-ui,sans-serif">• 1 GTP (= 1 ATP)</text><text x="455" y="392" font-size="11" font-weight="700" fill="#B42318" font-family="system-ui,sans-serif">Total per Glucose: ~30 to 32 ATP</text><text x="400" y="505" font-size="11" font-weight="400" text-anchor="middle" fill="#3D5A54" font-family="system-ui,sans-serif">Thiamine (B1) deficiency impairs pyruvate dehydrogenase, causing pyruvate accumulation and lactic acidosis in beriberi.</text></svg>'''
    with open(os.path.join(OUT_DIR, "bio-glycolysis-tca.svg"), "w") as f:
        f.write(svg)

